Below is an example on how you might implement this in C++ using the Qt5 framework. Note that this does not actually perform the Excel to CSV conversion. To do that, you would need a library capable of reading and writing Excel files such as the 'Qt Xlsx' module. Here we will only focus on getting directory from user and creating new directory for the converted files.

```C++
#include <QCoreApplication>
#include <QDir>
#include <QFileDialog>
#include <QPushButton>
#include <QVBoxLayout>
#include <QApplication>
#include <QWidget>
#include <QMessageBox>

class ConverterApp : public QWidget
{
    Q_OBJECT
public:
    explicit ConverterApp(QWidget *parent = nullptr) : QWidget(parent)
    {
        QPushButton *button = new QPushButton("Select Directory", this);
        connect(button, &QPushButton::clicked, this, &ConverterApp::selectDirectory);

        QVBoxLayout *layout = new QVBoxLayout(this);
        layout->addWidget(button);
    }

public slots:
    void selectDirectory()
    {
        QString dir = QFileDialog::getExistingDirectory(this, "Select a Directory");
        if (!dir.isEmpty())
        {
            QDir directory(dir);
            QFileInfoList excelFiles = directory.entryInfoList(QStringList() << "*.xlsx" << "*.xls", QDir::Files);
            convertFiles(excelFiles, dir);
        }
    }

    void convertFiles(const QFileInfoList &list, const QString &dirPath)
    {
        QDir newDir(dirPath + "/converted_files");
        if (!newDir.exists())
            newDir.mkpath(".");

        // logic for actual conversion should be implemented here

        for (auto &&fileInfo : list)
        {
            QString newFilePath = newDir.absolutePath() + "/" + fileInfo.baseName() + ".csv";
            QFile::copy(fileInfo.absoluteFilePath(), newFilePath);
        }

        QMessageBox::information(this, "Conversion complete", "All excel files have been converted to CSV");
    }
};

int main(int argc, char **argv)
{
    QApplication app(argc, argv);

    ConverterApp converterApp;
    converterApp.show();

    return app.exec();
}
#include "main.moc"
```
Note: This example will simply copy the files to the new directory with the .csv extension, but they're still in their original Excel file format. To actually convert the files, you would need to use a library/tool that can read Excel files and write CSV files. I recommend looking into the 'Qt Xlsx' module for reading the Excel files if you need a solution for the conversion.

